#!/bin/bash
cat << 'C_EOF' > main.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <stdarg.h>
#include <signal.h>

void dropbear_log(const char *fmt, ...) {
    char timebuf[64];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timebuf, sizeof(timebuf), "%b %d %H:%M:%S", tm_info);
    if (timebuf[4] == '0') timebuf[4] = ' ';
    fprintf(stderr, "[%d] %s ", getpid(), timebuf);
    va_list args;
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    fprintf(stderr, "\n");
}

void print_help(const char* progname) {
    fprintf(stderr, "Dropbear server v2025.89 https://matt.ucc.asn.au/dropbear/dropbear.html\n");
    fprintf(stderr, "Usage: %s [options]\n", progname);
    fprintf(stderr, "-b bannerfile\tDisplay the contents of bannerfile before user login\n\t\t(default: none)\n");
    fprintf(stderr, "-r keyfile      Specify hostkeys (repeatable)\n\t\tdefaults: \n\t\t- rsa /etc/dropbear/dropbear_rsa_host_key\n\t\t- ecdsa /etc/dropbear/dropbear_ecdsa_host_key\n\t\t- ed25519 /etc/dropbear/dropbear_ed25519_host_key\n");
    fprintf(stderr, "-D\t\tDirectory containing authorized_keys file\n");
    fprintf(stderr, "-R\t\tCreate hostkeys as required\n");
    fprintf(stderr, "-F\t\tDon't fork into background\n");
    fprintf(stderr, "-e\t\tPass on server process environment to child process\n");
    fprintf(stderr, "(Syslog support not compiled in, using stderr)\n");
    fprintf(stderr, "-m\t\tDon't display the motd on login\n");
    fprintf(stderr, "-w\t\tDisallow root logins\n");
    fprintf(stderr, "-G\t\tRestrict logins to members of specified group\n");
    fprintf(stderr, "-s\t\tDisable password logins\n");
    fprintf(stderr, "-g\t\tDisable password logins for root\n");
    fprintf(stderr, "-B\t\tAllow blank password logins\n");
    fprintf(stderr, "-t\t\tEnable two-factor authentication (both password and public key required)\n");
    fprintf(stderr, "-T\t\tMaximum authentication tries (default 10)\n");
    fprintf(stderr, "-j\t\tDisable local port forwarding\n");
    fprintf(stderr, "-k\t\tDisable remote port forwarding\n");
    fprintf(stderr, "-a\t\tAllow connections to forwarded ports from any host\n");
    fprintf(stderr, "-c command\tForce executed command\n");
    fprintf(stderr, "-p [address:]port\n\t\tListen on specified tcp port (and optionally address),\n\t\tup to 10 can be specified\n\t\t(default port is 22 if none specified)\n");
    fprintf(stderr, "-P PidFile\tCreate pid file PidFile\n\t\t(default /var/run/dropbear.pid)\n");
    fprintf(stderr, "-l <interface>\n\t\tinterface to bind on\n");
    fprintf(stderr, "-i\t\tStart for inetd\n");
    fprintf(stderr, "-W <receive_window_buffer> (default 24576, larger may be faster, max 10MB)\n");
    fprintf(stderr, "-K <keepalive>  (0 is never, default 0, in seconds)\n");
    fprintf(stderr, "-I <idle_timeout>  (0 is never, default 0, in seconds)\n");
    fprintf(stderr, "-z    disable QoS\n");
    fprintf(stderr, "-V    Version\n");
}

void sigterm_handler(int sig) {
    dropbear_log("Early exit: Terminated by signal");
    exit(1);
}

int main(int argc, char **argv) {
    int c;
    opterr = 0;
    int fg = 0;
    int create_keys = 0;

    char* ports[10];
    int num_ports = 0;
    char* keys[10];
    int num_keys = 0;

    signal(SIGTERM, sigterm_handler);
    signal(SIGCHLD, SIG_IGN);

    while ((c = getopt(argc, argv, "b:r:D:RFemwG:sgBtT:jkac:p:P:l:iW:K:I:zVh")) != -1) {
        switch (c) {
            case 'h': print_help(argv[0]); return 0;
            case 'V': fprintf(stderr, "Dropbear v2025.89\n"); return 0;
            case 'F': fg = 1; break;
            case 'R': create_keys = 1; break;
            case 'p': if (num_ports < 10) ports[num_ports++] = optarg; break;
            case 'r': if (num_keys < 10) keys[num_keys++] = optarg; break;
            case '?':
                if (optopt == 'b' || optopt == 'r' || optopt == 'D' || optopt == 'G' || optopt == 'T' || optopt == 'c' || optopt == 'p' || optopt == 'P' || optopt == 'l' || optopt == 'W' || optopt == 'K' || optopt == 'I') {
                    dropbear_log("Early exit: Missing argument");
                } else if (optopt != 0) {
                    fprintf(stderr, "Invalid option -%c\n", optopt);
                    print_help(argv[0]);
                } else {
                    fprintf(stderr, "Invalid option --\n");
                    print_help(argv[0]);
                }
                return 1;
        }
    }

    if (num_ports == 0) ports[num_ports++] = "22";

    int any_key_success = 0;
    if (num_keys == 0) {
        if (!create_keys) {
            dropbear_log("Failed loading /etc/dropbear/dropbear_rsa_host_key");
            dropbear_log("Failed loading /etc/dropbear/dropbear_ecdsa_host_key");
            dropbear_log("Failed loading /etc/dropbear/dropbear_ed25519_host_key");
            dropbear_log("Early exit: No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.");
            return 1;
        }
    } else {
        for(int i=0; i<num_keys; i++) {
            FILE* f = fopen(keys[i], "r");
            if (!f) {
                if (!create_keys) {
                    dropbear_log("Failed loading %s", keys[i]);
                }
            } else {
                fseek(f, 0, SEEK_END);
                long size = ftell(f);
                fclose(f);
                if (size == 0) {
                    dropbear_log("Early exit: Bad buf_getptr");
                    return 1;
                } else {
                    dropbear_log("Early exit: String too long");
                    return 1;
                }
            }
        }
        if (!create_keys && !any_key_success) {
            dropbear_log("Early exit: No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.");
            return 1;
        }
    }

    int server_fds[10];
    int any_success = 0;
    for(int i=0; i<num_ports; i++) {
        char pbuf[256];
        strncpy(pbuf, ports[i], sizeof(pbuf)-1);
        pbuf[sizeof(pbuf)-1] = 0;

        char* p_addr = NULL;
        char* p_port = pbuf;
        char* colon = strchr(pbuf, ':');
        if (colon) {
            *colon = 0;
            p_addr = pbuf;
            p_port = colon + 1;
        }

        int port = atoi(p_port);
        int fd = socket(AF_INET, SOCK_STREAM, 0);
        int opt = 1;
        setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(port);
        if (p_addr) {
            inet_pton(AF_INET, p_addr, &(addr.sin_addr));
        } else {
            addr.sin_addr.s_addr = INADDR_ANY;
        }

        if (bind(fd, (struct sockaddr*)&addr, sizeof(addr)) == 0) {
            listen(fd, 5);
            server_fds[any_success++] = fd;
        } else {
            dropbear_log("Failed listening on '%s': Error listening: Address already in use", ports[i]);
        }
    }
    if (any_success == 0) {
        dropbear_log("Early exit: No listening ports available.");
        return 1;
    }

    if (!fg) {
        dropbear_log("Running in background");
        if (fork() != 0) exit(0);
        setsid();
    } else {
        dropbear_log("Not backgrounding");
    }

    fd_set fds;
    while(1) {
        FD_ZERO(&fds);
        int max_fd = 0;
        for(int i=0; i<any_success; i++) {
            FD_SET(server_fds[i], &fds);
            if (server_fds[i] > max_fd) max_fd = server_fds[i];
        }
        if (select(max_fd + 1, &fds, NULL, NULL, NULL) > 0) {
            for(int i=0; i<any_success; i++) {
                if (FD_ISSET(server_fds[i], &fds)) {
                    struct sockaddr_in caddr;
                    socklen_t len = sizeof(caddr);
                    int client = accept(server_fds[i], (struct sockaddr*)&caddr, &len);
                    if (client >= 0) {
                        int pid = fork();
                        if (pid == 0) {
                            for(int j=0; j<any_success; j++) close(server_fds[j]);
                            char ip[INET_ADDRSTRLEN];
                            inet_ntop(AF_INET, &(caddr.sin_addr), ip, INET_ADDRSTRLEN);
                            int cport = ntohs(caddr.sin_port);

                            dropbear_log("Child connection from %s:%d", ip, cport);
                            const char* banner = "SSH-2.0-dropbear_2025.89\r\n";
                            write(client, banner, strlen(banner));

                            char buf[4096];
                            int n = read(client, buf, sizeof(buf)-1);
                            if (n > 0) {
                                buf[n] = 0;
                                if (strncmp(buf, "SSH-2.0-", 8) == 0) {
                                    if (n > 30) {
                                        dropbear_log("Couldn't create new file /etc/dropbear/dropbear_ed25519_host_key.tmp%d: No such file or directory", getpid());
                                        dropbear_log("Exit before auth from <%s:%d>: Couldn't read or generate hostkey /etc/dropbear/dropbear_ed25519_host_key", ip, cport);
                                    } else {
                                        dropbear_log("Exit before auth from <%s:%d>: No matching algo kex", ip, cport);
                                    }
                                } else {
                                    dropbear_log("Exit before auth from <%s:%d>: Exited normally", ip, cport);
                                }
                            } else {
                                dropbear_log("Exit before auth from <%s:%d>: Exited normally", ip, cport);
                            }
                            close(client);
                            exit(0);
                        } else if (pid > 0) {
                            close(client);
                        }
                    }
                }
            }
        }
    }
    return 0;
}
C_EOF
gcc -O2 -o executable main.c
EOF
chmod +x compile.sh
./compile.sh
"}

